    "reader.s1": "'हर शब्द' खोलें और कोई टेक्स्ट फ़ोटो या पेस्ट करें।",
    "reader.s2": "टेक्स्ट खुलता है और ऊपर उसके मुख्य शब्द चिह्नित होते हैं।",
