    "say.title": "उच्चारण का अभ्यास करें",
    "say.desc": "सुनें कि कोई शब्द कैसा लगता है और उसे ज़ोर से बोलने का अभ्यास करें।",
    "say.s1": "'बोलकर देखें' खोलें और शब्द का उच्चारण सुनें।",
    "say.s2": "शब्द बोलते हुए खुद को रिकॉर्ड करें।",
    "say.s3": "तुरंत प्रतिक्रिया पाएँ: बिलकुल सही, लगभग, या थोड़ा और।",
    "install.title": "अपने फ़ोन में Gadit इंस्टॉल करें",
    "install.desc": "Gadit को होम स्क्रीन में जोड़ें ताकि यह ऐप की तरह खुले।",
