    "install.s2": "'होम स्क्रीन में जोड़ें' चुनें।",
    "install.s3": "Gadit का आइकन आपकी होम स्क्रीन पर दिखता है।",
    "pair.title": "अपने बच्चे का डिवाइस जोड़ें",
    "pair.desc": "QR या 6 अंकों के कोड से बच्चे का फ़ोन अपने परिवार से जोड़ें।",
    "pair.s1": "'परिवार' में, बच्चे के पास 'डिवाइस जोड़ें' पर टैप करें।",
    "pair.s2": "एक QR कोड और 6 अंकों का कोड दिखता है।",
    "pair.s3": "बच्चे के फ़ोन पर: साइन इन करें, फिर 'किसी परिवार से जुड़ रहे हैं? अपना कोड दर्ज करें'।",
