    "say.title": "አነባበብ ተለማመድ",
    "say.desc": "አንድ ቃል እንዴት እንደሚሰማ አዳምጥ እና ጮክ ብለህ መናገር ተለማመድ።",
    "say.s1": "'ተናገረው' ን ክፈት እና የቃሉን አነባበብ አዳምጥ።",
    "say.s2": "ቃሉን ስትናገር ራስህን ቅረጽ።",
    "say.s3": "ወዲያውኑ ግብረ መልስ ያግኙ፦ ትክክል፣ ተቃርቧል፣ ወይም ገና ነው።",
