    "pair.s1": "በ'ቤተሰብ' ውስጥ፣ ከልጅዎ አጠገብ 'መሣሪያ አገናኝ' ን ይንኩ።",
    "pair.s2": "የ QR ኮድ እና የ6 አኃዝ ኮድ ይታያሉ።",
